```c
#include <ftw.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pwd.h>
#include <ctype.h>
#include <libgen.h>

// Global variables to pass data to callback function
static char source_abs[PATH_MAX];
static char dest_abs[PATH_MAX];
static int move_operation = 0;
static char *excluded_exts[6];
static int num_excluded = 0;

// Function prototypes
int process_file(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf);
int mkdir_p(const char *path);

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s source_dir dest_dir (-cp or -mv) [exts...]
", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *source_dir = argv[1];
    const char *dest_dir = argv[2];
    const char *option = argv[3];
    int ext_count = argc - 4;
    const char **extensions = (const char **)argv + 4;

    if (strcmp(option, "-cp") != 0 && strcmp(option, "-mv") != 0) {
        fprintf(stderr, "Invalid option. Must be -cp or -mv
");
        exit(EXIT_FAILURE);
    }
    move_operation = (strcmp(option, "-mv") == 0);

    if (ext_count > 6) {
        fprintf(stderr, "Up to 6 extensions allowed.
");
        exit(EXIT_FAILURE);
    }

    // Process extensions
    for (int i = 0; i < ext_count; i++) {
        const char *ext = extensions[i];
        char *ext_copy = malloc(10);
        if (!ext_copy) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        ext_copy[0] = '.';
        size_t len = strlen(ext);
        for (size_t j = 0; j < len && j < 6; j++) {
            ext_copy[j + 1] = tolower((unsigned char)ext[j]);
        }
        ext_copy[len + 1] = '\0';
        excluded_exts[i] = ext_copy;
    }
    num_excluded = ext_count;

    // Get home directory
    struct passwd *pw = getpwuid(getuid());
    if (!pw) {
        perror("getpwuid");
        exit(EXIT_FAILURE);
    }
    const char *home_dir = pw->pw_dir;

    // Get absolute path of source
    if (realpath(source_dir, source_abs) == NULL) {
        perror("realpath source");
        exit(EXIT_FAILURE);
    }

    // Check source exists and is under home
    if (access(source_abs, F_OK) != 0) {
        perror("Source directory does not exist");
        exit(EXIT_FAILURE);
    }
    if (strncmp(source_abs, home_dir, strlen(home_dir)) != 0) {
        fprintf(stderr, "Source directory not in home hierarchy
");
        exit(EXIT_FAILURE);
    }

    // Build dest_abs
    if (realpath(dest_dir, dest_abs) == NULL) {
        // Destination does not exist, build path
        if (dest_dir[0] == '/') {
            strncpy(dest_abs, dest_dir, PATH_MAX);
        } else {
            char cwd[PATH_MAX];
            if (getcwd(cwd, sizeof(cwd)) == NULL) {
                perror("getcwd");
                exit(EXIT_FAILURE);
            }
            snprintf(dest_abs, PATH_MAX, "%s/%s", cwd, dest_dir);
        }
    }

    // Check destination under home
    if (strncmp(dest_abs, home_dir, strlen(home_dir)) != 0) {
        fprintf(stderr, "Destination directory not in home hierarchy
");
        exit(EXIT_FAILURE);
    }

    // Check source and dest are not same
    if (strcmp(source_abs, dest_abs) == 0) {
        fprintf(stderr, "Source and destination are the same
");
        exit(EXIT_FAILURE);
    }

    // Traverse source directory
    int flags = FTW_DEPTH | FTW_PHYS;
    if (nftw(source_abs, process_file, 20, flags) != 0) {
        perror("nftw");
        exit(EXIT_FAILURE);
    }

    // Cleanup
    for (int i = 0; i < num_excluded; i++) {
        free(excluded_exts[i]);
    }

    return 0;
}

int process_file(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    const char *relative_part = fpath + strlen(source_abs);
    char dest_path[PATH_MAX];
    snprintf(dest_path, sizeof(dest_path), "%s%s", dest_abs, relative_part);

    int exclude = 0;

    switch (typeflag) {
        case FTW_F: // Regular file
            if (num_excluded > 0) {
                const char *ext = strrchr(fpath, '.');
                if (ext != NULL) {
                    for (int i = 0; i < num_excluded; i++) {
                        if (strcasecmp(ext, excluded_exts[i]) == 0) {
                            exclude = 1;
                            break;
                        }
                    }
                }
            }

            if (!exclude) {
                // Create parent directories
                char *dir = strdup(dest_path);
                if (!dir) {
                    perror("strdup");
                    return FTW_STOP;
                }
                char *parent_dir = dirname(dir);
                if (mkdir_p(parent_dir) != 0) {
                    fprintf(stderr, "Failed to create directory %s: %s\n", parent_dir, strerror(errno));
                    free(dir);
                    return FTW_STOP;
                }
                free(dir);

                // Copy file
                int src_fd = open(fpath, O_RDONLY);
                if (src_fd == -1) {
                    perror("open source file");
                    return FTW_STOP;
                }

                mode_t mode = sb->st_mode;
                int dest_fd = open(dest_path, O_WRONLY | O_CREAT | O_TRUNC, mode);
                if (dest_fd == -1) {
                    perror("open destination file");
                    close(src_fd);
                    return FTW_STOP;
                }

                char buffer[4096];
                ssize_t bytes_read;
                while ((bytes_read = read(src_fd, buffer, sizeof(buffer))) > 0) {
                    if (write(dest_fd, buffer, bytes_read) != bytes_read) {
                        perror("write");
                        close(src_fd);
                        close(dest_fd);
                        return FTW_STOP;
                    }
                }

                close(src_fd);
                close(dest_fd);
            }

            // If moving, delete file
            if (move_operation && !exclude) {
                if (unlink(fpath) != 0) {
                    perror("unlink");
                    return FTW_STOP;
                }
            }
            break;

        case FTW_DIR: // Directory
            if (mkdir_p(dest_path) != 0 && errno != EEXIST) {
                fprintf(stderr, "Failed to create directory %s: %s\n", dest_path, strerror(errno));
                return FTW_STOP;
            }

            if (move_operation) {
                if (rmdir(fpath) != 0 && errno != ENOENT) {
                    perror("rmdir");
                    return FTW_STOP;
                }
            }
            break;

        default:
            break;
    }

    return 0;
}

int mkdir_p(const char *path) {
    char *tmp = strdup(path);
    if (!tmp) return -1;

    char *p = tmp;
    if (*p == '/') p++;

    int status = 0;

    while (*p) {
        while (*p && *p != '/') p++;
        if (*p == '\0') break;
        *p = '\0';

        if (mkdir(tmp, 0777) < 0) {
            if (errno != EEXIST) {
                status = -1;
                break;
            }
        }

        *p = '/';
        p++;
    }

    if (status == 0 && mkdir(tmp, 0777) < 0) {
        if (errno != EEXIST) status = -1;
    }

    free(tmp);
    return status;
}
```

