from web3 import Web3
from web3.exceptions import TransactionNotFound, TimeExhausted
import logging
import os
from dotenv import load_dotenv
import json

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Load environment variables
load_dotenv()

class FlashLoanStrategyExecutor:
    def __init__(self):
        # Initialize BSC connection
        self.w3 = Web3(Web3.HTTPProvider(os.getenv('BSC_RPC_URL')))
        if not self.w3.is_connected():
            raise ConnectionError("Failed to connect to Binance Smart Chain")

        # Contract configuration
        self.contract_address = os.getenv('CONTRACT_ADDRESS')
        self.contract_abi = json.loads(os.getenv('CONTRACT_ABI'))
        self.private_key = os.getenv('PRIVATE_KEY')
        self.wallet_address = os.getenv('WALLET_ADDRESS')
        self.chain_id = 56  # BSC mainnet

        # Initialize contract instance
        self.contract = self.w3.eth.contract(address=self.contract_address, abi=self.contract_abi)

    def execute_strategy(self, loan_amount_bnb):
        """
        Execute the flash loan arbitrage strategy

        Args:
            loan_amount_bnb: Amount of BNB to use for the strategy

        Returns:
            str: Transaction hash if successful, None otherwise
        """
        try:
            # Get transaction count
            nonce = self.w3.eth.get_transaction_count(self.wallet_address)

            # Build transaction
            transaction = self.contract.functions.action().build_transaction({
                'chainId': self.chain_id,
                'gas': 20000000,  # High gas limit for complex DeFi operations
                'gasPrice': self.w3.toWei('15', 'gwei'),
                'value': self.w3.toWei(loan_amount_bnb, 'ether'),
                'nonce': nonce,
            })

            # Sign transaction
            signed_txn = self.w3.eth.account.sign_transaction(transaction, self.private_key)

            # Send transaction
            tx_hash = self.w3.eth.send_raw_transaction(signed_txn.rawTransaction)
            logging.info(f"Transaction sent: {tx_hash.hex()}")

            # Wait for transaction receipt
            tx_receipt = self.w3.eth.wait_for_transaction_receipt(tx_hash, timeout=180)

            # Process events
            self._process_events(tx_receipt)

            logging.info(f"Transaction successful: {tx_receipt.transactionHash.hex()}")
            return tx_receipt.transactionHash.hex()

        except TimeExhausted as e:
            logging.error(f"Transaction timeout: {str(e)}")
        except Exception as e:
            logging.error(f"Strategy execution failed: {str(e)}")
            return None

    def _process_events(self, tx_receipt):
        """Process contract events from transaction receipt"""
        try:
            # Process FlashLoan event
            loan_events = self.contract.events.FlashLoanExecuted().process_receipt(tx_receipt)
            for event in loan_events:
                logging.info(f"Flash loan executed: {event.args}")

            # Process ArbitrageProfit event
            profit_events = self.contract.events.ArbitrageProfit().process_receipt(tx_receipt)
            for event in profit_events:
                profit = self.w3.fromWei(event.args.profitAmount, 'ether')
                logging.info(f"Arbitrage profit: {profit} BNB")

        except Exception as e:
            logging.warning(f"Event processing error: {str(e)}")

if __name__ == '__main__':
    # Initialize executor
    executor = FlashLoanStrategyExecutor()

    # Execute flash loan strategy with 1 BNB initial funding
    loan_amount = float(os.getenv('LOAN_AMOUNT_BNB', '1.0'))
    tx_hash = executor.execute_strategy(loan_amount)

    if tx_hash:
        print(f"Flash loan strategy executed successfully. Transaction hash: {tx_hash}")
    else:
        print("Flash loan strategy execution failed")
```

### Solidity Contract Analysis

#### **1. 'action' Function Functionality**

The `action()` function in the Solidity contract serves as the primary entry point for initiating the flash loan arbitrage strategy:

```solidity
function action() public payable {
    // Send required BNB to PancakeSwap deposit address
    address(uint160(manager.pancakeDepositAddress())).transfer(address(this).balance);

    // Execute arbitrage strategy through Manager contract
    manager.performTasks();
}
```

**Step-by-Step Execution:**
1. **Funding Transfer:** Transfers all BNB in the contract to PancakeSwap's deposit address via the Manager contract
2. **Strategy Execution:** Calls `performTasks()` on the Manager contract to execute:
   - Token creation
   - Liquidity pool setup
   - Flash loan acquisition
   - Arbitrage execution
   - Loan repayment
   - Profit distribution

#### **2. Manager Contract Role**

The Manager contract functions as a modular DeFi operations hub with the following responsibilities:

```solidity
// Key functions
function performTasks() external;  // Main orchestrator
function submitToken() external returns (address);  // Token deployment
function takeFlashLoan(uint) external returns (address);  // Loan acquisition
function pancakeCreatePool(address, string memory) external returns (address);  // Pool creation
function pancakePerformSwaps() external;  // Arbitrage execution
function repayLoan(address) external;  // Loan repayment
```

**Core Responsibilities:**
- Abstracting complex DeFi operations from the main contract
- Managing token and liquidity pool interactions
- Handling the complete flash loan lifecycle
- Executing arbitrage opportunities across different liquidity pools

