Here's a comprehensive implementation of a multi-page documentation system with Firebase integration, optimized for clarity and avoiding repetition of prior content:

### Next.js Multi-Page System Implementation

#### 1. File Structure for Dynamic Routing
```
app/
└── docs/
    ├── [id]/     # Dynamic route for individual documents
    │   └── page.tsx
    ├── page.tsx    # Index page listing all documents
    └── new/        # Page for creating new documents
        └── page.tsx
```

#### 2. Dynamic Document Page Component
```tsx
// app/docs/[id]/page.tsx
"use client"; // Required for client-side hooks

import { useState, useEffect } from "react";
import { MarkdownRX } from "markdown-rx";
import { usePathname } from "next/navigation";

export default function DocumentationPage({ 
  params 
}: { 
  params: { id: string } 
}) {
  const [content, setContent] = useState("# Loading...");
  const [isEditing, setIsEditing] = useState(false);
  const [validation, setValidation] = useState<any>(null);
  const [document, setDocument] = useState<any>(null);
  const pathname = usePathname();

  // Load document content and metadata
  useEffect(() => {
    const loadDocument = async () => {
      const res = await fetch(`/api/docs/${params.id}`);
      const data = await res.json();

      if (data.content) {
        setContent(data.content);
        setDocument(data.metadata);
      }
    };
    loadDocument();
  }, [params.id]);

  // Validate markdown content
  const handleValidate = async () => {
    const res = await fetch("/api/validate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content }),
    });
    const result = await res.json();
    setValidation(result);
  };

  // Save document changes
  const handleSave = async () => {
    const res = await fetch("/api/docs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id: params.id, content }),
    });

    if (res.ok) {
      setIsEditing(false);
      alert("Document saved successfully!");
    }
