```java
public class Ticket {
    private static final int MT = 1000; // Maximum ticket number before cycling
    private int next = 0; // Tracks the next ticket number

    public synchronized int ticket() {
        next = (next % MT) + 1;
        return next;
    }
}

public class Counter {
    private static final int MT = 1000; // Maximum serve number before cycling
    private int serve = 1; // Tracks the current serving number

    public synchronized void getcheese(int ticket_num) throws InterruptedException {
        while (ticket_num != serve) {
            wait(); // Wait for notification
        }
        // Once served, update the serve counter
        serve = (serve % MT) + 1;
        notifyAll(); // Notify waiting threads
    }
}
