      context = 'initial';
      encodedBits = [];
      for i = 1:length(sequence)
          if isequal(context, 'initial') || sequence(i-1) == 0
              p0 = transitionProbs{0}(1);
              p1 = transitionProbs{0}(2);
          else
              p0 = transitionProbs{1}(1);
              p1 = transitionProbs{1}(2);
          end
          range = high - low;
          if sequence(i) == 0
              high = low + p0 * range;
          else
              low = low + p0 * range;
          end
          context = sequence(i);
          % Renormalization step
          while high < 0.5 || low >= 0.5
              if high < 0.5
                  encodedBits = [encodedBits 0];
                  low = low * 2;
                  high = high * 2;
              elseif low >= 0.5
                  encodedBits = [encodedBits 1];
                  low = (low - 0.5) * 2;
                  high = (high - 0.5) * 2;
              end
          end
      end
  end
  ```

#### 3. **Noisy Channel Simulation**
